<?php $pageTitle = 'Candidates'; include __DIR__ . '/partials/header.php'; ?>
<section class="page-heading"><div><p class="eyebrow">Election setup</p><h1>Candidates</h1><p class="muted">Link registered students to positions. Self-voting is excluded when a ballot is generated.</p></div></section>
<div class="panel narrow-panel"><form method="post" action="/candidates" class="stack-form"><label>Student<select name="student_id" required><option value="">Select student</option><?php foreach ($students as $student): ?><option value="<?= (int) $student['id'] ?>"><?= htmlspecialchars($student['first_name'] . ' ' . $student['last_name'] . ' · ' . $student['student_number'], ENT_QUOTES, 'UTF-8') ?></option><?php endforeach; ?></select></label><label>Position<select name="position_id" required><option value="">Select position</option><?php foreach ($positions as $position): ?><option value="<?= (int) $position['id'] ?>"><?= htmlspecialchars($position['name'], ENT_QUOTES, 'UTF-8') ?></option><?php endforeach; ?></select></label><button class="button button-primary" type="submit">Assign candidate</button></form></div>
<div class="panel table-panel"><table><thead><tr><th>Candidate</th><th>Position</th><th>Programme</th></tr></thead><tbody><?php foreach ($candidates as $candidate): ?><tr><td><?= htmlspecialchars($candidate['first_name'] . ' ' . $candidate['last_name'], ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars($candidate['position_name'], ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars($candidate['programme'], ENT_QUOTES, 'UTF-8') ?></td></tr><?php endforeach; ?><?php if (!$candidates): ?><tr><td colspan="3" class="muted">No candidates assigned yet.</td></tr><?php endif; ?></tbody></table></div>
<?php include __DIR__ . '/partials/footer.php'; ?>
